const crypto = require('crypto');

const item = $input.first();
const headers = {};
for (const [k, v] of Object.entries(item?.json?.headers || {})) {
  headers[k.toLowerCase()] = Array.isArray(v) ? v[0] : v;
}

const secret = $env.N8N_WEBHOOK_SECRET || '';
if (!secret || secret.length < 16) {
  throw new Error('Missing or short N8N_WEBHOOK_SECRET environment variable (min 16 chars)');
}

let rawBuffer = null;
try {
  rawBuffer = await this.helpers.getBinaryDataBuffer(0, 'data');
} catch {
  const inlineBase64 = item?.binary?.data?.data;
  if (inlineBase64) {
    rawBuffer = Buffer.from(inlineBase64, 'base64');
  }
}

const rawBody = rawBuffer && rawBuffer.length > 0
  ? rawBuffer.toString('utf8')
  : JSON.stringify(item?.json?.body || {});

const timestamp = String(headers['x-lendloop-timestamp'] || '').trim();
const signatureHeader = String(headers['x-lendloop-signature'] || '').trim();

if (!/^\d+$/.test(timestamp)) {
  return [{ json: { valid: false, reason: 'Malformed X-LendLoop-Timestamp header.' } }];
}

const nowSeconds = Math.floor(Date.now() / 1000);
if (Math.abs(nowSeconds - Number(timestamp)) > 300) {
  return [{ json: { valid: false, reason: 'Webhook timestamp outside +/-300s replay window.' } }];
}

const providedHex = signatureHeader.replace(/^sha256=/i, '').toLowerCase();
if (!/^[0-9a-f]{64}$/.test(providedHex)) {
  return [{ json: { valid: false, reason: 'Malformed HMAC signature header.' } }];
}

const expectedHex = crypto
  .createHmac('sha256', secret)
  .update(`${timestamp}.${rawBody}`)
  .digest('hex');

const a = Buffer.from(providedHex, 'hex');
const b = Buffer.from(expectedHex, 'hex');
if (a.length !== b.length || !crypto.timingSafeEqual(a, b)) {
  return [{ json: { valid: false, reason: 'Invalid HMAC-SHA256 signature.' } }];
}

const body = JSON.parse(rawBody);
const eventId = String(body.eventId || '');
const eventType = String(body.eventType || '');
const loanId = String(body.loanId || '');
const toolName = String(body.toolName || 'Tool');
const startDate = String(body.startDate || '');
const endDate = String(body.endDate || '');
const recipientEmail = String(body.recipientEmail || '');
const recipientFirstName = String(body.recipientFirstName || 'Neighbor');

if (!eventId || !eventType || !loanId || !recipientEmail) {
  throw new Error('Verified webhook payload missing required minimal fields.');
}

const subjectMap = {
  loan_requested: `[LendLoop] New borrow request: ${toolName}`,
  loan_approved: `[LendLoop] Borrow request approved: ${toolName}`,
  loan_declined: `[LendLoop] Borrow request declined: ${toolName}`,
  loan_returned: `[LendLoop] Return confirmed: ${toolName}`,
};

const textMap = {
  loan_requested: `Hi ${recipientFirstName},\n\nA neighbor requested to borrow your "${toolName}" from ${startDate} to ${endDate}.\n\nOpen LendLoop (/dashboard) to approve or decline this request.\n\n— LendLoop`,
  loan_approved: `Hi ${recipientFirstName},\n\nYour borrow request for "${toolName}" (${startDate} to ${endDate}) was approved!\n\nPlease coordinate pickup and return it by ${endDate}.\n\n— LendLoop`,
  loan_declined: `Hi ${recipientFirstName},\n\nYour borrow request for "${toolName}" (${startDate} to ${endDate}) was declined.\n\nBrowse other available neighborhood tools in LendLoop.\n\n— LendLoop`,
  loan_returned: `Hi ${recipientFirstName},\n\nYour loan for "${toolName}" (${startDate} to ${endDate}) has been marked returned. Thanks for sharing!\n\n— LendLoop`,
};

return [{
  json: {
    valid: true,
    eventId,
    eventType,
    loanId,
    recipientEmail,
    recipientFirstName,
    subject: subjectMap[eventType] || `[LendLoop] Loan update: ${toolName}`,
    text: textMap[eventType] || `Hi ${recipientFirstName},\n\nLoan update for "${toolName}": ${body.status}.\n\n— LendLoop`,
  },
}];

const crypto = require('crypto');

const evt = $('Verify HMAC & Format Copy').item.json;
const secret = $env.CONVEX_AUTOMATION_SECRET || '';
if (!secret || secret.length < 16) {
  throw new Error('Missing or short CONVEX_AUTOMATION_SECRET environment variable (min 16 chars)');
}
const timestamp = String(Math.floor(Date.now() / 1000));
const rawBody = JSON.stringify({
  idempotencyKey: evt.eventId,
  loanId: evt.loanId,
  status: 'delivered',
  summary: 'Notification email sent via n8n',
});
const signatureHex = crypto
  .createHmac('sha256', secret)
  .update(`${timestamp}.${rawBody}`)
  .digest('hex');

return [{
  json: {
    eventId: evt.eventId,
    timestamp,
    signature: `sha256=${signatureHex}`,
    rawBody,
  },
}];
